{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — Integrative care for the whole you</title>
  <meta name="description" content="Holistic, evidence-minded integrative medicine focused on lifestyle, labs, and long-form care. No quick fixes — whole-person support." />
  <link rel="stylesheet" href="assets/css/styles.css" />
  <script defer src="assets/js/main.js"></script>
</head>
<body>
  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav" aria-label="Primary navigation">
        <ul>
          <li><a href="services.html">Offerings</a></li>
          <li><a href="conditions.html">Concerns</a></li>
          <li><a href="approach.html">Method</a></li>
          <li><a href="pricing.html">Invest</a></li>
          <li><a href="about.html">Meet</a></li>
          <li><a href="book.html" class="pill">Book</a></li>
          <li><a href="contact.html">Reach</a></li>
        </ul>
      </nav>
      <button class="menu-toggle" aria-expanded="false" aria-label="Open menu">☰</button>
    </div>
  </header>

  <main>

    <!-- HERO -->
    <section id="hero" class="hero">
      <div class="wrap hero-grid" style="background-image:url('assets/img/pattern.svg');">
        <div class="hero-copy">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="tagline">{{TAGLINE}} — a playful, pragmatic approach to your vitality.</p>
          <p class="intro">We combine thoughtful diagnostics, lifestyle medicine, and personalized plans to help you feel steadier, sleep deeper, and move through life with more ease. No promises of miracle cures — only thoughtful, whole-person care.</p>
          <div class="hero-ctas">
            <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="btn ghost" href="about.html">Meet the clinician</a>
          </div>
        </div>
        <div class="hero-card">
          <div class="card-inner">
            <header>
              <strong>New Patient Intensive</strong>
              <span class="muted">Comprehensive first visit — 90 minutes</span>
            </header>
            <ul class="mini-list">
              <li>Full health history & lifestyle review</li>
              <li>Focused physical exam & tailored labs (optional)</li>
              <li>Clear 90-day plan + follow-up rhythm</li>
            </ul>
            <a class="btn small ripple-cta" href="book.html">Start the intake</a>
          </div>
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id="myths" class="section myths">
      <div class="wrap">
        <h2>Myths vs. Practical Truths</h2>
        <div class="grid-2">
          <div class="card soft">
            <h3>Myth: Holistic care is vague</h3>
            <p>Practical truth: We use clear assessments — labs, validated questionnaires, and clinical reasoning — to make targeted plans that adapt to you.</p>
          </div>
          <div class="card soft">
            <h3>Myth: It promises cures</h3>
            <p>Practical truth: We won’t promise cures. The goal is measurable improvement in symptoms, function, and resilience through whole-person strategies.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PILLARS -->
    <section id="pillars" class="section pillars">
      <div class="wrap">
        <h2>Core pillars of care</h2>
        <p class="lead">A gentle architecture for change — small, evidence-minded steps that stack up over time.</p>
        <div class="pillars-grid">
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="10"/></svg>
            <h3>Nutrition + Gut</h3>
            <p>Practical guidance to support digestion, energy, and inflammation; food as data rather than dogma.</p>
          </div>
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="4"/></svg>
            <h3>Sleep & Rhythm</h3>
            <p>Behavioral tools and circadian-friendly tweaks to restore restorative sleep and daytime focus.</p>
          </div>
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2 L20 21 L4 21 Z"/></svg>
            <h3>Stress Resilience</h3>
            <p>Simple practices to reduce physiological load and rebuild adaptive capacity — breath, movement, mindset.</p>
          </div>
          <div class="pillar">
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6 a6 6 0 1 0 0 12 a6 6 0 1 0 0-12"/></svg>
            <h3>Targeted Testing</h3>
            <p>Optional labs when needed: hormones, micronutrients, metabolic markers — used as educational tools, not magic bullets.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- CASE NOTES -->
    <section id="case_notes" class="section case-notes">
      <div class="wrap">
        <h2>Case notes (anonymized sketches)</h2>
        <p class="muted">Examples show typical pathways and learning — each person’s course is unique.</p>
        <div class="notes-grid">
          <article class="note">
            <h3>Stress + Sleep</h3>
            <p class="summary">Patient had months of fragmented sleep and daytime fog. We prioritized sleep windows, light exposure, and a short breathing protocol. Over 12 weeks, subjective sleep quality improved and daytime focus increased.</p>
            <small class="muted">Not a guarantee; individual results vary.</small>
          </article>
          <article class="note">
            <h3>Digestive comfort</h3>
            <p class="summary">After symptom mapping and simple dietary experiments, inflammatory markers were reviewed and a stepwise plan reduced bloating and irregularity.</p>
            <small class="muted">Educational testing and gradual interventions used; consult for personalized plans.</small>
          </article>
        </div>
      </div>
    </section>

    <!-- FAQ -->
    <section id="faq" class="section faq">
      <div class="wrap">
        <h2>Questions people ask</h2>
        <div class="faq-list">
          <details>
            <summary>What is an Intensive visit?</summary>
            <div class="answer">An Intensive is a longer initial visit (usually 60–120 minutes) to build a thorough history, baseline metrics, and a clear 90-day plan. Optional labs or imaging are discussed as educational tools.</div>
          </details>
          <details>
            <summary>Do you promise cures?</summary>
            <div class="answer">No. We focus on measurable improvements and sustainable changes. Medicine is about probability, not guarantees.</div>
          </details>
          <details>
            <summary>Will insurance cover visits?</summary>
            <div class="answer">Coverage varies. We provide superbills and can discuss billing options during intake.</div>
          </details>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section id="cta" class="cta">
      <div class="wrap cta-grid">
        <div>
          <h2>Ready to begin a different approach?</h2>
          <p>Book an Intensive to map out a clear, compassionate plan tailored to your life.</p>
        </div>
        <div class="cta-actions">
          <a class="btn large primary ripple-cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="muted-link" href="contact.html">Questions? Email <span class="nowrap">{{EMAIL}}</span></a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <p>&copy; <span class="year">2026</span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <nav aria-label="Footer">
        <ul>
          <li><a href="about.html">The clinician ({{PRACTITIONER_NAME}}, {{CREDENTIALS}})</a></li>
          <li><a href="services.html">What we offer</a></li>
          <li><a href="privacy.html">Privacy</a></li>
        </ul>
      </nav>
    </div>
  </footer>

</body>
</html>"} 
