{"path":"assets/css/styles.css","content":"/* Zen minimal + playful premium accents */
:root{
  --bg:#fbfbfb;
  --muted:#6b7280;
  --accent-1:#6EE7B7;
  --accent-2:#60A5FA;
  --ink:#0f172a;
  --glass:rgba(255,255,255,0.7);
  --radius:12px;
  --max:1100px;
}
*{box-sizing:border-box}
html,body{height:100%}
body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--ink);background:linear-gradient(180deg,var(--bg),#fff);}
.wrap{max-width:var(--max);margin:0 auto;padding:28px}
.site-header{backdrop-filter:blur(6px);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));border-bottom:1px solid rgba(15,23,42,0.05)}
.site-header .wrap{display:flex;align-items:center;gap:18px}
.logo{font-weight:700;color:var(--ink);text-decoration:none;font-size:1.05rem}
.nav ul{list-style:none;margin:0;padding:0;display:flex;gap:14px;align-items:center}
.nav a{color:var(--ink);text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.pill{background:linear-gradient(90deg,var(--accent-1),var(--accent-2));color:white;padding:8px 12px}
.menu-toggle{display:none;background:none;border:0;font-size:1.2rem}

.hero{padding:36px 0}
.hero-grid{display:grid;grid-template-columns:1fr 320px;gap:28px;align-items:stretch;padding:44px;border-radius:18px;background:linear-gradient(135deg, rgba(96,165,250,0.06), rgba(110,231,183,0.04));box-shadow:0 6px 30px rgba(12,18,32,0.06)}
.hero h1{margin:0;font-size:2rem}
.tagline{color:var(--accent-2);font-weight:600}
.intro{color:var(--muted);margin-top:12px}
.btn{display:inline-block;text-decoration:none;border-radius:10px;padding:10px 14px;font-weight:600}
.btn.primary{background:linear-gradient(90deg,var(--accent-1),var(--accent-2));color:white}
.btn.ghost{background:transparent;border:1px solid rgba(15,23,42,0.06);color:var(--ink)}
.btn.small{padding:8px 10px;font-size:0.9rem}
.card-inner{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));padding:18px;border-radius:14px;box-shadow:0 6px 20px rgba(12,18,32,0.06)}
.mini-list{margin:12px 0 18px 0;padding:0 0 0 18px;color:var(--muted)}

.section{padding:54px 0}
.section h2{margin:0 0 12px 0}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.card.soft{padding:18px;border-radius:12px;background:linear-gradient(180deg,#fff,#fcfeff);box-shadow:0 8px 24px rgba(12,18,32,0.04)}
.pillars-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:18px}
.pillar{background:linear-gradient(180deg,rgba(255,255,255,0.88),#fff);padding:18px;border-radius:12px;text-align:center}
.pillar .icon{width:46px;height:46px;fill:linear-gradient(90deg,var(--accent-1),var(--accent-2));opacity:0.14;margin:0 auto 10px auto;background:linear-gradient(90deg,var(--accent-1),var(--accent-2));-webkit-mask-image:none}
.lead{color:var(--muted)}
.case-notes .notes-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}
.note{background:#fff;padding:16px;border-radius:12px;box-shadow:0 8px 24px rgba(12,18,32,0.03)}
.muted{color:var(--muted)}
.faq details{background:#fff;padding:14px;border-radius:12px;margin-bottom:10px}
.faq summary{cursor:pointer;font-weight:600}
.cta{background:linear-gradient(90deg,rgba(96,165,250,0.06),rgba(110,231,183,0.04));padding:26px;border-radius:12px}
.cta-grid{display:flex;justify-content:space-between;align-items:center;gap:20px}
.btn.large{padding:14px 20px;font-size:1.05rem}
.muted-link{color:var(--muted);text-decoration:none}
.nowrap{white-space:nowrap}
.site-footer{padding:28px 0;border-top:1px solid rgba(15,23,42,0.04);font-size:0.95rem}
.site-footer a{color:var(--ink);text-decoration:none}
.year{font-weight:700}

/* Responsive tweaks */
@media (max-width:880px){
  .hero-grid{grid-template-columns:1fr;}
  .pillars-grid{grid-template-columns:repeat(2,1fr)}
  .case-notes .notes-grid{grid-template-columns:1fr}
  .nav{display:none}
  .menu-toggle{display:inline-block}
}

/* Ripple effect for CTAs */
.ripple-cta{position:relative;overflow:hidden}
.ripple-ctawave{position:absolute;border-radius:999px;background:rgba(255,255,255,0.35);transform:scale(0);animation:ripple 600ms linear;pointer-events:none}
@keyframes ripple{to{transform:scale(4);opacity:0}}

/* Use the SVG pattern as subtle background */
.hero, .section{background-image:url('/assets/img/pattern.svg');background-repeat:repeat;opacity:1}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Mobile menu toggle
  const menuButton=document.querySelector('.menu-toggle');
  const nav=document.querySelector('.nav');
  if(menuButton){
    menuButton.addEventListener('click',()=>{
      const expanded=menuButton.getAttribute('aria-expanded')==='true';
      menuButton.setAttribute('aria-expanded',!expanded);
      if(nav) nav.style.display = expanded ? 'none' : 'block';
    });
  }

  // FAQ polyfill for keyboard
  document.querySelectorAll('.faq details').forEach(d=>{
    d.addEventListener('keydown',e=>{
      if(e.key==='Enter' || e.key===' '){
        e.preventDefault(); d.open = !d.open;
      }
    });
  });

  // Ripple effect on CTAs
  function rippleHandler(e){
    const btn=e.currentTarget;
    const rect=btn.getBoundingClientRect();
    const wave=document.createElement('span');
    wave.className='ripple-ctawave';
    const size=Math.max(rect.width,rect.height)*2;
    wave.style.width=wave.style.height=size+'px';
    wave.style.left=(e.clientX-rect.left - size/2)+'px';
    wave.style.top=(e.clientY-rect.top - size/2)+'px';
    btn.appendChild(wave);
    setTimeout(()=>wave.remove(),650);
  }
  document.querySelectorAll('.ripple-cta').forEach(el=>el.addEventListener('click',rippleHandler));

  // Smooth scroll for in-page CTA anchors
  document.querySelectorAll('a[href^="#"]').forEach(a=>{
    a.addEventListener('click',function(e){
      const target=document.querySelector(this.getAttribute('href'));
      if(target){e.preventDefault();target.scrollIntoView({behavior:'smooth',block:'start'});}
    });
  });

  // Small accessibility: focus outline toggle
  function handleFirstTab(e){
    if(e.key==='Tab') document.body.classList.add('user-is-tabbing');
    window.removeEventListener('keydown',handleFirstTab);
  }
  window.addEventListener('keydown',handleFirstTab);
})();"} 
